contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint128 vBase,
        uint128 vNft,
        uint16 feeRate,
        uint256[] memory inputIds,
        uint256[] memory outputIds
    ) public payable {
        require(vNft > 0);
        require(inputIds.length == outputIds.length);
        require(inputIds.length > 0);
        require(feeRate <= 5000);

        c.initialize(
            address(0),
            address(this),
            vBase,
            vNft,
            0, // changeFee = 0
            feeRate,
            bytes32(0), // no merkle proof required
            false,
            false
        );

        uint256 nftBalanceBefore = c.balanceOf(address(c));

        uint256[] memory inputWeights = new uint256[](inputIds.length);
        uint256[] memory outputWeights = new uint256[](outputIds.length);

        for (uint256 i = 0; i < inputIds.length; i++) {
            inputWeights[i] = 1e18;
            outputWeights[i] = 1e18;
        }

        C.MerkleMultiProof memory inputProof;
        inputProof.proof = new bytes32[](0);
        inputProof.flags = new bool[](0);

        C.MerkleMultiProof memory outputProof;
        outputProof.proof = new bytes32[](0);
        outputProof.flags = new bool[](0);

        IStolenNftOracle.Message[] memory stolenProofs = new IStolenNftOracle.Message[](0);

        c.change(inputIds, inputWeights, inputProof, stolenProofs, outputIds, outputWeights, outputProof);

        uint256 nftBalanceAfter = c.balanceOf(address(c));

        assert(nftBalanceAfter >= nftBalanceBefore);
        assert(nftBalanceAfter == nftBalanceBefore);
    }

    receive() external payable {}
}

